 export function formatMoney(cents: number | null, currency = "usd"): string {
 	if (cents == null) return "—";
 	const symbols: Record<string, string> = {
 		usd: "$",
 		eur: "€",
 		gbp: "£",
 		inr: "₹",
 		jpy: "¥",
 	};
 	const symbol = symbols[currency.toLowerCase()] ?? "";
