 		}
 	}

 	return (
 		<div className="flex items-center gap-2">
 			<Button
 				size="sm"
 				disabled={pending !== null}
 				onClick={() => decide("approve")}
 			>
 				{pending === "approve" ? "Sending…" : "Approve & send"}
 			</Button>
 			<Button
 				size="sm"
 				variant="outline"
 				disabled={pending !== null}
 				onClick={() => decide("reject")}
